<script setup lang="ts">import {ref} from 'vue';import PageHeader from '@/components/shared/PageHeader.vue';import BaseBadge from '@/components/base/BaseBadge.vue';import {MessageCircle,Send,RefreshCw,CheckCheck} from 'lucide-vue-next';import {WhatsAppService} from '@/services';const step=ref(0),input=ref('');const messages=ref([{from:'user',text:'Olá, preciso de suporte.'},{from:'bot',text:'Olá, Mariana! Identifiquei você como funcionária da Secretaria. Qual problema está acontecendo?'}]);const prompts=['Em qual equipamento o problema ocorre?','Qual o impacto deste problema no seu trabalho?','Obrigado! Estou criando o seu chamado...'];function advance(){const answer=input.value||['A impressora da secretaria não está imprimindo.','Impressora IMP-012.','Não consigo emitir documentos para atendimento.'][step.value];messages.value.push({from:'user',text:answer});input.value='';setTimeout(()=>{if(step.value<3)messages.value.push({from:'bot',text:prompts[step.value]});else messages.value.push({from:'bot',text:`Chamado #${WhatsAppService.simulateProtocol()} registrado com sucesso. A equipe de TI foi notificada.`});step.value++},250)}function reset(){step.value=0;messages.value=messages.value.slice(0,2)}</script>
<template><PageHeader title="WhatsApp" description="Simulação do chatbot para abertura automatizada de chamados"><BaseBadge label="Integração simulada"/><button class="btn btn-secondary" @click="reset"><RefreshCw class="size-4"/>Reiniciar conversa</button></PageHeader><div class="grid h-[calc(100vh-165px)] grid-cols-[minmax(520px,1fr)_420px] gap-4"><section class="card flex min-h-0 flex-col overflow-hidden"><div class="flex items-center gap-3 bg-[#075e54] px-4 py-3 text-white"><div class="flex size-9 items-center justify-center rounded-full bg-white/15"><MessageCircle class="size-5"/></div><div><b class="text-sm">AeroTI Atendimento</b><div class="text-[10px] text-emerald-100">online · chatbot de suporte</div></div></div><div class="scrollbar flex-1 space-y-3 overflow-auto bg-[#efeae2] p-5 dark:bg-slate-900"><div v-for="(m,i) in messages" :key="i" class="flex" :class="m.from==='user'?'justify-end':'justify-start'"><div class="max-w-[75%] rounded-lg px-3 py-2 text-xs shadow-sm" :class="m.from==='user'?'bg-[#d9fdd3] text-slate-800':'bg-white text-slate-800'"><p class="leading-5">{{m.text}}</p><div class="mt-1 flex justify-end gap-1 text-[9px] text-slate-400">10:{{20+i}}<CheckCheck class="size-3 text-blue-500"/></div></div></div></div><div class="flex gap-2 border-t p-3 dark:border-slate-700"><input v-model="input" class="field" placeholder="Digite uma resposta para continuar a simulação" @keyup.enter="advance"/><button class="btn btn-primary" @click="advance"><Send class="size-4"/></button></div></section><aside class="card overflow-auto p-5"><div class="flex items-center justify-between"><h2 class="text-sm font-bold">Chamado em geração</h2><BaseBadge :label="step>=4?'Criado':'Coletando dados'"/></div><div class="mt-5 space-y-4 text-xs"><div v-for="[k,v,done] in [['Funcionário','Mariana Costa',true],['Setor','Secretaria',true],['Problema','Impressora não imprime',step>=1],['Equipamento','IMP-012 · Impressora Secretaria',step>=2],['Impacto','Atendimento parcialmente interrompido',step>=3],['Protocolo',step>=4?'TI-0248':'Aguardando conclusão',step>=4]]" :key="String(k)" class="border-b pb-3 dark:border-slate-700"><div class="text-[10px] uppercase tracking-wide text-slate-400">{{k}}</div><div class="mt-1 font-semibold" :class="!done&&'text-slate-400'">{{done?v:'Aguardando resposta...'}}</div></div></div><div class="mt-5 rounded-md border border-blue-200 bg-blue-50 p-3 text-xs text-blue-800 dark:border-blue-900 dark:bg-blue-950 dark:text-blue-200"><b>Fluxo de demonstração</b><p class="mt-1 leading-5">Esta tela não envia mensagens reais. O WhatsAppService está isolado para futura substituição por uma API oficial.</p></div></aside></div></template>
